package com.github.fntz.omhs.internal

import com.github.fntz.omhs.{AsyncResult, CommonResponse, Route, Rule}
import io.netty.handler.codec.http.HttpMethod

/**
 * This class describes a function which we should run when a rule is matched
 *  for user-request
 * @param rule - set of restrictions
 * @param runner - function generated by macros for `~>`
 */
class ExecutableRule(
  val rule: Rule,
  private val runner: List[ParamDef[_]] => AsyncResult = ExecutableRule.defaultRunner
) {

  lazy val method: HttpMethod = rule.currentMethod

  def ::[T <: ExecutableRule](other: T): Route = {
    val r = new Route
    r.addRule(this)
      .addRule(other)
  }

  def run(defs: List[ParamDef[_]]): AsyncResult = runner(defs)

  override def toString: String = {
    s"Rule[$rule]"
  }
}

object ExecutableRule {
  private val defaultRunner: List[ParamDef[_]] => AsyncResult =
    _ => AsyncResult.completed(CommonResponse.empty)
}
